import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormBuilder, FormGroup, Validators } from '@angular/forms';
import { TransacaoService, Transacao } from '../../services/transacao.service';

// ========================================================================
// COMPONENTE
// ========================================================================

@Component({
  selector: 'app-transacoes',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './transacoes.component.html',
  styleUrls: ['./transacoes.component.scss']
})
export class TransacoesComponent implements OnInit {
  // ====================================================================
  // ESTADO
  // ====================================================================

  transacoes: Transacao[] = [];
  mostrarForm = false;
  isLoading = false;
  isSaving = false;
  hasError = false;
  errorMessage = '';
  editandoId: number | null = null;

  transacaoForm: FormGroup;

  // Categorias fixas para o select (você pode obter da API se preferir)
  categorias = [
    { id: 1, nome: 'Alimentação' },
    { id: 2, nome: 'Transporte' },
    { id: 3, nome: 'Saúde' },
    { id: 4, nome: 'Entretenimento' },
    { id: 5, nome: 'Educação' },
    { id: 6, nome: 'Utilidades' },
    { id: 7, nome: 'Salário' },
    { id: 8, nome: 'Investimentos' },
    { id: 9, nome: 'Outros' }
  ];

  // ====================================================================
  // CONSTRUTOR
  // ====================================================================

  constructor(
    private transacaoService: TransacaoService,
    private fb: FormBuilder
  ) {
    this.transacaoForm = this.criarFormulario();
  }

  // ====================================================================
  // LIFECYCLE
  // ====================================================================

  ngOnInit(): void {
    this.carregarTransacoes();
  }

  // ====================================================================
  // MÉTODOS PRIVADOS
  // ====================================================================

  /**
   * Cria um novo FormGroup para o formulário de transações
   */
  private criarFormulario(): FormGroup {
    return this.fb.group({
      categoria_id: ['', [Validators.required]],
      valor: ['', [Validators.required, Validators.min(0.01)]],
      tipo: ['receita', [Validators.required]],
      data: ['', [Validators.required]],
      descricao: ['', [Validators.required, Validators.minLength(3)]]
    });
  }

  /**
   * Reseta o formulário aos valores padrão
   */
  private resetarFormulario(): void {
    this.transacaoForm.reset({
      categoria_id: '',
      valor: '',
      tipo: 'receita',
      data: this.obterDataAtual(),
      descricao: ''
    });
    this.editandoId = null;
  }

  /**
   * Obtém a data atual no formato YYYY-MM-DD
   */
  private obterDataAtual(): string {
    const hoje = new Date();
    return hoje.toISOString().split('T')[0];
  }

  /**
   * Formata o valor para moeda
   */
  private formatarMoeda(valor: number): string {
    return new Intl.NumberFormat('pt-PT', {
      style: 'currency',
      currency: 'EUR'
    }).format(valor);
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - CARREGAMENTO
  // ====================================================================

  /**
   * Carrega a lista de transações da API
   */
  carregarTransacoes(): void {
    this.isLoading = true;
    this.hasError = false;

    this.transacaoService.listar().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          const data = response.data as Transacao[];
          this.transacoes = Array.isArray(data) ? data : [data];
        } else {
          this.transacoes = [];
        }
        this.isLoading = false;
      },
      error: (error) => {
        console.error('Erro ao carregar transações:', error);
        this.hasError = true;
        this.errorMessage = 'Erro ao carregar as transações. Tente novamente.';
        this.isLoading = false;
      }
    });
  }

  // ====================================================================
  // MÉTODOS PÚBLICOS - FORMULÁRIO
  // ====================================================================

  /**
   * Alterna a visibilidade do formulário
   */
  toggleFormulario(): void {
    this.mostrarForm = !this.mostrarForm;
    if (!this.mostrarForm) {
      this.resetarFormulario();
    } else {
      // Define a data atual quando abre o formulário
      this.transacaoForm.patchValue({
        data: this.obterDataAtual()
      });
    }
  }

  /**
   * Abre o formulário para editar uma transação
   */
  editar(transacao: Transacao): void {
    this.editandoId = transacao.id || null;
    this.transacaoForm.patchValue({
      categoria_id: transacao.categoria_id,
      valor: transacao.valor,
      tipo: transacao.tipo,
      data: transacao.data,
      descricao: transacao.descricao
    });
    this.mostrarForm = true;
  }

  /**
   * Cancela a edição/criação e fecha o formulário
   */
  cancelar(): void {
    this.mostrarForm = false;
    this.resetarFormulario();
  }

  /**
   * Salva a transação (cria ou atualiza)
   */
  salvar(): void {
    if (!this.transacaoForm.valid) {
      this.errorMessage = 'Por favor, preencha todos os campos corretamente.';
      return;
    }

    this.isSaving = true;
    const formValue = this.transacaoForm.value;

    if (this.editandoId) {
      // Atualizar transação existente
      this.transacaoService.atualizar(this.editandoId, formValue).subscribe({
        next: () => {
          this.carregarTransacoes();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao atualizar transação:', error);
          this.errorMessage = 'Erro ao atualizar a transação. Tente novamente.';
          this.isSaving = false;
        }
      });
    } else {
      // Criar nova transação
      this.transacaoService.criar(formValue).subscribe({
        next: () => {
          this.carregarTransacoes();
          this.cancelar();
          this.isSaving = false;
        },
        error: (error) => {
          console.error('Erro ao criar transação:', error);
          this.errorMessage = 'Erro ao criar a transação. Tente novamente.';
          this.isSaving = false;
        }
      });
    }
  }

  /**
   * Remove uma transação
   */
  deletar(transacao: Transacao): void {
    if (!transacao.id) return;

    if (confirm(`Tem a certeza que deseja eliminar esta transação (${this.formatarMoeda(transacao.valor)})?`)) {
      this.transacaoService.remover(transacao.id).subscribe({
        next: () => {
          this.carregarTransacoes();
        },
        error: (error) => {
          console.error('Erro ao deletar transação:', error);
          this.errorMessage = 'Erro ao eliminar a transação. Tente novamente.';
        }
      });
    }
  }

  /**
   * Retorna o nome da categoria pelo ID
   */
  obterNomeCategoria(categoriaId: number): string {
    return this.categorias.find(c => c.id === categoriaId)?.nome || 'Desconhecido';
  }

  /**
   * Formata valor para exibição
   */
  formatarValor(valor: number): string {
    return this.formatarMoeda(valor);
  }

  /**
   * Formata data para exibição (DD/MM/YYYY)
   */
  formatarData(data: string): string {
    const date = new Date(data + 'T00:00:00');
    return new Intl.DateTimeFormat('pt-PT').format(date);
  }

  /**
   * Verifica se está em modo edição
   */
  isEditando(): boolean {
    return this.editandoId !== null;
  }

  /**
   * Retorna o título do formulário
   */
  getTituloFormulario(): string {
    return this.editandoId ? 'Editar Transação' : 'Nova Transação';
  }

  /**
   * Retorna o texto do botão de salvar
   */
  getTextoBotaoSalvar(): string {
    return this.editandoId ? 'Atualizar' : 'Criar';
  }
}
<!-- ======================================================================== -->
<!-- CABEÇALHO COM TÍTULO E BOTÃO -->
<!-- ======================================================================== -->

<div class="transacoes-container">
  <div class="transacoes-header">
    <h1>Transações Financeiras</h1>
    <button 
      class="btn btn-primary" 
      (click)="toggleFormulario()"
      [disabled]="isLoading">
      <span *ngIf="!mostrarForm">+ Nova Transação</span>
      <span *ngIf="mostrarForm">✕ Cancelar</span>
    </button>
  </div>

  <!-- ======================================================================== -->
  <!-- MENSAGEM DE ERRO -->
  <!-- ======================================================================== -->

  <div *ngIf="hasError" class="alert alert-error">
    <strong>Erro:</strong> {{ errorMessage }}
    <button class="alert-close" (click)="hasError = false">✕</button>
  </div>

  <!-- ======================================================================== -->
  <!-- ESTADO DE CARREGAMENTO -->
  <!-- ======================================================================== -->

  <div *ngIf="isLoading" class="loading-container">
    <div class="spinner"></div>
    <p>Carregando transações...</p>
  </div>

  <!-- ======================================================================== -->
  <!-- FORMULÁRIO -->
  <!-- ======================================================================== -->

  <div *ngIf="mostrarForm && !isLoading" class="formulario-container">
    <h2>{{ getTituloFormulario() }}</h2>
    
    <form [formGroup]="transacaoForm" (ngSubmit)="salvar()" class="transacao-form">
      <!-- Campo: Categoria -->
      <div class="form-group">
        <label for="categoria_id">Categoria</label>
        <select 
          id="categoria_id"
          formControlName="categoria_id"
          class="form-control">
          <option value="">Selecione uma categoria</option>
          <option *ngFor="let cat of categorias" [value]="cat.id">
            {{ cat.nome }}
          </option>
        </select>
        <span *ngIf="transacaoForm.get('categoria_id')?.invalid && transacaoForm.get('categoria_id')?.touched" 
              class="error-message">
          Categoria é obrigatória
        </span>
      </div>

      <!-- Campo: Tipo -->
      <div class="form-group">
        <label for="tipo">Tipo</label>
        <div class="tipo-options">
          <label class="radio-label">
            <input 
              type="radio" 
              id="tipo-receita"
              value="receita" 
              formControlName="tipo"
              class="radio-input">
            <span class="radio-text receita">Receita</span>
          </label>
          <label class="radio-label">
            <input 
              type="radio" 
              id="tipo-despesa"
              value="despesa" 
              formControlName="tipo"
              class="radio-input">
            <span class="radio-text despesa">Despesa</span>
          </label>
        </div>
      </div>

      <!-- Campo: Valor -->
      <div class="form-group">
        <label for="valor">Valor (€)</label>
        <input 
          type="number" 
          id="valor"
          formControlName="valor"
          placeholder="0.00"
          step="0.01"
          min="0"
          class="form-control">
        <span *ngIf="transacaoForm.get('valor')?.invalid && transacaoForm.get('valor')?.touched" 
              class="error-message">
          <span *ngIf="transacaoForm.get('valor')?.errors?.['required']">Valor é obrigatório</span>
          <span *ngIf="transacaoForm.get('valor')?.errors?.['min']">Valor deve ser positivo</span>
        </span>
      </div>

      <!-- Campo: Data -->
      <div class="form-group">
        <label for="data">Data</label>
        <input 
          type="date" 
          id="data"
          formControlName="data"
          class="form-control">
        <span *ngIf="transacaoForm.get('data')?.invalid && transacaoForm.get('data')?.touched" 
              class="error-message">
          Data é obrigatória
        </span>
      </div>

      <!-- Campo: Descrição -->
      <div class="form-group">
        <label for="descricao">Descrição</label>
        <textarea 
          id="descricao"
          formControlName="descricao"
          placeholder="Descrição da transação..."
          rows="3"
          class="form-control"></textarea>
        <span *ngIf="transacaoForm.get('descricao')?.invalid && transacaoForm.get('descricao')?.touched" 
              class="error-message">
          <span *ngIf="transacaoForm.get('descricao')?.errors?.['required']">Descrição é obrigatória</span>
          <span *ngIf="transacaoForm.get('descricao')?.errors?.['minlength']">Descrição deve ter pelo menos 3 caracteres</span>
        </span>
      </div>

      <!-- Botões -->
      <div class="form-actions">
        <button 
          type="submit" 
          class="btn btn-success"
          [disabled]="!transacaoForm.valid || isSaving">
          <span *ngIf="!isSaving">{{ getTextoBotaoSalvar() }}</span>
          <span *ngIf="isSaving">Guardando...</span>
        </button>
        <button 
          type="button" 
          class="btn btn-secondary"
          (click)="cancelar()"
          [disabled]="isSaving">
          Cancelar
        </button>
      </div>
    </form>
  </div>

  <!-- ======================================================================== -->
  <!-- LISTA VAZIA -->
  <!-- ======================================================================== -->

  <div *ngIf="!isLoading && transacoes.length === 0 && !mostrarForm" class="empty-state">
    <div class="empty-icon">📊</div>
    <h3>Nenhuma transação registada</h3>
    <p>Clique em "+ Nova Transação" para começar a registar as suas transações financeiras.</p>
  </div>

  <!-- ======================================================================== -->
  <!-- TABELA (DESKTOP) E CARDS (MOBILE) -->
  <!-- ======================================================================== -->

  <div *ngIf="!isLoading && transacoes.length > 0 && !mostrarForm" class="transacoes-content">
    
    <!-- TABELA PARA DESKTOP -->
    <div class="transacoes-table-wrapper">
      <table class="transacoes-table">
        <thead>
          <tr>
            <th>Data</th>
            <th>Descrição</th>
            <th>Categoria</th>
            <th>Tipo</th>
            <th class="text-right">Valor</th>
            <th class="text-center">Ações</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let t of transacoes" [class.receita-row]="t.tipo === 'receita'" [class.despesa-row]="t.tipo === 'despesa'">
            <td class="data-cell">{{ formatarData(t.data) }}</td>
            <td class="descricao-cell">{{ t.descricao }}</td>
            <td class="categoria-cell">{{ obterNomeCategoria(t.categoria_id) }}</td>
            <td class="tipo-cell">
              <span [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
                {{ t.tipo === 'receita' ? '↓ Receita' : '↑ Despesa' }}
              </span>
            </td>
            <td class="valor-cell" [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
              <strong>{{ formatarValor(t.valor) }}</strong>
            </td>
            <td class="acoes-cell">
              <button class="btn btn-sm btn-primary" (click)="editar(t)" title="Editar">
                ✏️
              </button>
              <button class="btn btn-sm btn-error" (click)="deletar(t)" title="Eliminar">
                🗑️
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- CARDS PARA MOBILE -->
    <div class="transacoes-cards">
      <div *ngFor="let t of transacoes" class="transacao-card" [class.receita-card]="t.tipo === 'receita'" [class.despesa-card]="t.tipo === 'despesa'">
        <div class="card-header">
          <div class="card-date">{{ formatarData(t.data) }}</div>
          <div class="card-tipo" [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
            {{ t.tipo === 'receita' ? '↓ Receita' : '↑ Despesa' }}
          </div>
        </div>

        <div class="card-body">
          <div class="card-descricao">{{ t.descricao }}</div>
          <div class="card-categoria">{{ obterNomeCategoria(t.categoria_id) }}</div>
        </div>

        <div class="card-footer">
          <div class="card-valor" [class.receita]="t.tipo === 'receita'" [class.despesa]="t.tipo === 'despesa'">
            <strong>{{ formatarValor(t.valor) }}</strong>
          </div>
          <div class="card-acoes">
            <button class="btn btn-sm btn-primary" (click)="editar(t)" title="Editar">
              ✏️
            </button>
            <button class="btn btn-sm btn-error" (click)="deletar(t)" title="Eliminar">
              🗑️
            </button>
          </div>
        </div>
      </div>
    </div>

  </div>

</div>
